function longestRisingStretch(nums: number[]): number {
  let best = 1;
  for (let i = 0; i < nums.length; i++) {
    let j = i;
    while (j + 1 < nums.length && nums[j + 1] > nums[j]) j++;
    best = Math.max(best, j - i + 1);
  }
  return best;
}

