    def longestRisingStretch(self, nums: List[int]) -> int:
        best = 1
        for i in range(len(nums)):
            j = i
            while j + 1 < len(nums) and nums[j + 1] > nums[j]:
                j += 1
            best = max(best, j - i + 1)
